pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount, bytes memory data, address caller) public {
        vm.assume(caller != address(0) && caller != c.owner());
        vm.assume(target != address(c));
        vm.deal(address(c), amount);
        vm.prank(caller);
        bool ok = true;
        try c.sendMoney(target, amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
